<script setup lang="ts">
import { computed } from 'vue';
import { X,Upload,CheckCircle2,AlertCircle,Pause,Play,RefreshCw,FileCheck } from '@lucide/vue';
import { desk,safely,checkUploads,commitUploads,request,apiPath } from './store';
import { bytes,type Task } from './model';
const ready=computed(()=>desk.tasks.filter(t=>t.state==='review').length);
const queued=computed(()=>desk.tasks.some(t=>t.state==='queued'||t.state==='error'));
const labels:Record<string,string>={queued:'等待检查',uploading:'上传中',checking:'检查中',review:'等待确认',importing:'导入中',done:'已导入',error:'需要重试'};
async function discard(task:Task){if(task.plan?.id&&task.state!=='done')await request(apiPath(`/files/stage?id=${encodeURIComponent(task.plan.id)}`),'DELETE');desk.tasks=desk.tasks.filter(t=>t.id!==task.id);}
</script>
<template><section class="task-dock" aria-label="任务面板"><header><strong>文件导入</strong><span>{{desk.tasks.length}} 项</span><div class="actions-spacer"/><button class="text-action" :disabled="desk.uploading" @click="desk.tasks=desk.tasks.filter(t=>t.state!=='done')">清除完成项</button><button class="icon-button" aria-label="收起任务面板" @click="desk.tasksOpen=false"><X :size="16"/></button></header>
 <div class="task-list"><article v-for="task in desk.tasks" :key="task.id"><div class="task-symbol"><CheckCircle2 v-if="task.state==='done'" :size="18"/><AlertCircle v-else-if="task.state==='error'" :size="18"/><Upload v-else :size="18"/></div><div class="task-copy"><strong>{{task.name}}</strong><input v-if="task.state==='queued'||task.state==='error'" v-model="task.path" aria-label="保存路径"><small v-else>{{task.path}}</small><small v-if="task.error" class="error-copy">{{task.error}}</small><small v-else-if="task.plan?.metadata">{{task.plan.metadata.displayName||task.plan.metadata.componentId}} · {{task.plan.metadata.version}}</small><small v-if="task.plan?.replacements?.length">将归档旧模组：{{task.plan.replacements.map((p:any)=>p.path).join('、')}}</small></div><span class="subtle">{{bytes(task.size)}}</span><div class="task-progress"><span>{{labels[task.state]}}</span><progress v-if="task.state==='uploading'" :value="task.progress" max="100"/><select v-if="task.state==='review'" v-model="task.action" aria-label="导入动作"><option v-if="!task.plan?.existing&&!task.plan?.replacements?.length" value="ADD">新增</option><option v-if="task.plan?.existing&&!task.plan?.replacements?.length" value="OVERWRITE">归档后覆盖</option><option v-if="task.plan?.replacements?.length" value="REPLACE_MOD">替换旧模组</option><option value="SKIP">跳过</option></select></div><button v-if="!desk.uploading" class="icon-button" :aria-label="`移出清单 ${task.name}`" @click="safely(()=>discard(task))"><X :size="14"/></button></article><div v-if="!desk.tasks.length" class="empty-task">选择或拖入文件后，先检查，再确认导入。</div></div>
 <footer><span>导入完成后，到改动视图检查并发布。</span><div class="actions-spacer"/><button v-if="desk.uploading" @click="desk.uploadPaused=true"><Pause :size="14"/>暂停后续任务</button><button v-else :disabled="!queued" @click="safely(checkUploads)"><FileCheck :size="15"/>上传并检查</button><button class="accent" :disabled="!ready||desk.uploading" @click="safely(commitUploads)">确认导入 {{ready||''}}</button></footer>
</section></template>
